IPhoneCall target = core.CreateCallObject(line, "2001");
target.CallStateChanged += OnCallState;
target.Start();

var line = new LabLine("L1");
var oldCall = new LabCall("C1", line);
string displayed = "C2";
Action<LabCallEvent> bad = e => { if(e.State == LabCallState.Ended) displayed = "none"; };
oldCall.Changed += bad;
oldCall.HangUp(); // displayed變none
oldCall.Changed -= bad;
displayed = "C2";
Action<LabCallEvent> good = e => { if(e.CallId == displayed && e.State == LabCallState.Ended) displayed = "none"; };
oldCall.Changed += good;
oldCall.HangUp(); // displayed仍C2
oldCall.Changed -= good;
